using System.Text.Json;

namespace Zenigma.Api.Games.Puzzles;

/// <summary>
/// The practice levels shipped with the app, embedded in the API too (generated by tools/generators/puzzles) so that
/// a solution can be checked against the exact level the player was given.
/// </summary>
public sealed class PracticeLevels
{
    private readonly Dictionary<string, JsonElement[]> _levels = new();

    public PracticeLevels()
    {
        foreach (var game in PuzzleRules.Games)
        {
            using var stream = typeof(PracticeLevels).Assembly.GetManifestResourceStream($"levels/{game}.json")
                ?? throw new InvalidOperationException($"levels/{game}.json is not embedded.");
            using var doc = JsonDocument.Parse(stream);
            _levels[game] = doc.RootElement.EnumerateArray().Select(e => e.Clone()).ToArray();
        }
    }

    public int Count(string game) => _levels.TryGetValue(game, out var l) ? l.Length : 0;

    /// <summary>Level numbers start at 1.</summary>
    public JsonElement? Get(string game, int level) =>
        _levels.TryGetValue(game, out var l) && level >= 1 && level <= l.Length ? l[level - 1] : null;
}
